import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Find the most strongly associated feature with outcome
    strongest = None
    max_effect = 0
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            effect = abs(np.mean(feats.x[feats.y==1, i]) - np.mean(feats.x[feats.y==0, i]))
            if effect > max_effect:
                max_effect = effect
                strongest = fid

    # If no strong clinical variable found, try to find a driver using mutual info
    if not strongest:
        # Only proceed if we have enough features
        if len(feats.ids) > 0:
            try:
                mi_scores = mutual_info_classif(feats.x, feats.y)
                best_idx = np.argmax(mi_scores)
                if mi_scores[best_idx] > 0.01:  # threshold for relevance
                    strongest = feats.ids[best_idx]
            except:
                pass

    # If we found a driver, adjust for it by removing its effect
    if strongest and strongest in feats.ids:
        # Remove the effect of the driver from other features
        driver_idx = feats.column(strongest)
        driver_vals = feats.x[:, driver_idx]

        adjusted_features = []
        for i, fid in enumerate(feats.ids):
            if fid != strongest and i < feats.x.shape[1]:  # Ensure valid index
                feature_vals = feats.x[:, i]
                # Adjust for driver effect
                try:
                    slope, intercept, r_value, p_value, std_err = stats.linregress(driver_vals, feature_vals)
                    adjusted = feature_vals - (slope * driver_vals + intercept)
                    adjusted_features.append(adjusted)
                except:
                    adjusted_features.append(feature_vals)

        if len(adjusted_features) > 0:
            adjusted_features = np.array(adjusted_features).T

            # Calculate correlations between adjusted features and outcome
            correlations = []
            for i, fid in enumerate(feats.ids):
                if fid != strongest and i < feats.x.shape[1]:
                    try:
                        corr = np.corrcoef(feats.y, adjusted_features[:, i])[0, 1]
                        correlations.append((abs(corr), fid, i))
                    except:
                        continue

            correlations.sort(reverse=True)

            # Select top features that have strong correlation with outcome
            drivers = [strongest]
            columns = [strongest]

            # Add features that show strong association after adjustment
            for _, fid, idx in correlations[:MAX_DRIVERS-1]:
                if len(drivers) < MAX_DRIVERS and fid not in drivers:
                    drivers.append(fid)
                    columns.append(fid)
        else:
            # Fallback: simple approach
            drivers = [strongest]
            columns = [strongest]
    else:
        # No mechanism case or fallback - return empty drivers
        drivers = ()
        columns = ()

    # For simplicity in this example, we'll just use a few top features
    if not drivers:
        # Simple approach: select top features by correlation with outcome
        correlations = []
        for i, fid in enumerate(feats.ids):
            if i < feats.x.shape[1]:  # Ensure valid index
                try:
                    corr = np.corrcoef(feats.y, feats.x[:, i])[0, 1]
                    correlations.append((abs(corr), fid, i))
                except:
                    continue

        correlations.sort(reverse=True)
        # Limit to MAX_DRIVERS to avoid exceeding limit
        drivers = tuple([fid for _, fid, _ in correlations[:MAX_DRIVERS]])
        columns = drivers

        # Check for near-duplicates and remove them
        unique_drivers = []
        seen = set()
        for fid in drivers:
            if fid not in seen:
                seen.add(fid)
                unique_drivers.append(fid)

        drivers = tuple(unique_drivers)
        columns = unique_drivers

    # Create products based on correlated pairs
    products = []
    # Simple check for some known strong correlations
    correlated_pairs = [
        ('PSV2', 'ATUU4'), ('GOZY11', 'ATUU4'), ('DYLJ15B', 'ATUU4'),
        ('FXBJ12L', 'OZR2B'), ('GOZY11', 'PSV2'), ('PSV2', 'DYLJ15B')
    ]

    # Filter valid pairs
    valid_pairs = []
    for a, b in correlated_pairs:
        if a in columns and b in columns:
            valid_pairs.append((a, b))

    products = tuple(valid_pairs)

    # Loadings for weighted score
    loadings = {}
    for fid in columns:
        if fid in feats.ids:
            try:
                idx = feats.column(fid)
                if idx < feats.x.shape[1]:  # Ensure valid index
                    corr = np.corrcoef(feats.y, feats.x[:, idx])[0, 1]
                    loadings[fid] = corr
            except:
                loadings[fid] = 0.0

    # Ensure we don't exceed MAX_DRIVERS in drivers
    if len(drivers) > MAX_DRIVERS:
        drivers = drivers[:MAX_DRIVERS]

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
